1	//! The release executor.
2	//!
3	//! Every run starts from a fresh in-memory state and observes each provider
4	//! before acting, so a rerun adopts whatever an earlier run already landed.
5	
6	use std::collections::BTreeSet;
7	
8	use michi_graph::{Dag, Order};
9	
10	use callisto_model::{
11	    ApplyPermit, OperationEvent, OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId,
12	    ReleaseOperationRole, ReleaseRunEnvelopeV1, ReleaseStateError,
13	};
14	
15	use crate::GraphError;
16	
17	use super::release::{ReleasePreflight, ReleaseProviderSet};
18	use super::release_artifacts::VerifiedArtifactManifest;
19	use crate::error::ReleasePreconditionRequirement;
20	
21	/// Executes eligible operations one at a time.
22	///
23	/// The run `envelope` was created and validated before this call. Each
24	/// operation is observed once before any effect: an exact observation is
25	/// adopted as already satisfied, an absent one is published and confirmed,
26	/// and anything else stops the run before an effect is issued.
27	pub fn execute_release<P: ReleaseProviderSet + ?Sized>(
28	    capability: &P,
29	    permit: &ApplyPermit,
30	    envelope: &ReleaseRunEnvelopeV1,
31	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
32	) -> Result<ReleaseExecutionStateV1, GraphError> {
33	    let intent = capability.intent();
34	    require_verified_artifact_manifest(intent, artifacts)?;
35	    envelope
36	        .validate_for_intent(intent)
37	        .map_err(|source| GraphError::ReleaseRunEnvelope { source })?;
38	    let mut state = ReleaseExecutionStateV1::new(intent, envelope.clone())
39	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
40	    let dag = operation_dag(intent)?;
41	    // Registry publishes issued but not yet seen on their registry; they stay `Attempting` until they are.
42	    let mut issued = BTreeSet::new();
43	    let mut wave: Option<ConfirmationWave> = None;
44	    loop {
45	        let Some(operation) = eligible_in(&dag, &state, &issued).first().cloned() else {
46	            let Some(open) = wave.as_mut() else {
47	                break;
48	            };
49	            settle_issued(capability, artifacts, &mut state, &mut issued, open)?;
50	            if issued.is_empty() {
51	                wave = None;
52	            }
53	            continue;
54	        };
55	        capability.recheck_trust()?;
56	        match capability.preflight(&operation, artifacts)? {
57	            ReleasePreflight::AlreadySatisfied { evidence } => {
58	                warn_if_registry_version_adopted(&operation);
59	                apply(
60	                    &mut state,
61	                    &operation,
62	                    &OperationEvent::ObservedExactBeforeEffect { evidence },
63	                )?;
64	            }
65	            ReleasePreflight::Proceed { proof } => {
66	                let attempt = OperationEvent::Attempt { proof };
67	                apply(&mut state, &operation, &attempt)?;
68	                // The proof stays borrowed from the recorded attempt: only an
69	                // attempt may authorize the effect that follows it.
70	                let OperationEvent::Attempt { proof } = &attempt else {
71	                    return Err(GraphError::ReleaseInvariant {
72	                        detail: "the attempt event just built is not an Attempt".to_owned(),
73	                    });
74	                };
75	                if capability.defers_confirmation(&operation) {
76	                    capability.issue(permit, proof, &operation, artifacts)?;
77	                    wave.get_or_insert_with(|| ConfirmationWave::open(capability.now()));
78	                    issued.insert(operation);
79	                } else {
80	                    let evidence = capability.publish(permit, proof, &operation, artifacts)?;
81	                    apply(&mut state, &operation, &OperationEvent::Confirmed { evidence })?;
82	                }
83	            }
84	        }
85	    }
86	    require_terminal_success(intent, &state)?;
87	    Ok(state)
88	}
89	
90	fn warn_if_registry_version_adopted(operation: &ReleaseOperationId) {
91	    let package = match &operation.role {
92	        ReleaseOperationRole::RegistryPublish { .. } => &operation.package,
93	        ReleaseOperationRole::PlatformPublish { platform, .. } => platform.name(),
94	        _ => return,
95	    };
96	    eprintln!(
97	        "warning: {package} {} is already published; skipping",
98	        operation.version
99	    );
100	}
101	
102	/// The single seam through which this executor changes state.
103	fn apply(
104	    state: &mut ReleaseExecutionStateV1,
105	    operation: &ReleaseOperationId,
106	    event: &OperationEvent,
107	) -> Result<(), GraphError> {
108	    state
109	        .apply(operation, event)
110	        .map(|_| ())
111	        .map_err(|source| match source {
112	            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
113	            source => GraphError::ReleaseExecutionState { source },
114	        })
115	}
116	
117	/// Refuses to report success until every operation has an observed terminal
118	/// success state.
119	fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
120	    let count = intent
121	        .operations
122	        .iter()
123	        .filter(|operation| {
124	            !state
125	                .operation_state(operation.id())
126	                .is_some_and(OperationState::is_success)
127	        })
128	        .count();
129	    if count == 0 {
130	        Ok(())
131	    } else {
132	        Err(GraphError::ReleaseIncomplete { count })
133	    }
134	}
135	
136	/// Requires the verification capability whenever `intent` declares compiled
137	/// binary slots. Its private constructor already proved both manifest binding
138	/// and local byte/attestation identity.
139	fn require_verified_artifact_manifest(
140	    intent: &ReleaseIntentV1,
141	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
142	) -> Result<(), GraphError> {
143	    match (intent.artifact_slots.is_empty(), artifacts) {
144	        (true, None) => Ok(()),
145	        (true, Some(artifacts)) if !callisto_model::python_publishes(intent).is_empty() => {
146	            require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest()))
147	        }
148	        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
149	            detail: "verified artifact manifest supplied for a release intent with nothing to seal".to_owned(),
150	        }),
151	        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
152	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
153	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
154	        }),
155	    }
156	}
157	
158	/// Validates the serializable manifest independently of local byte and
159	/// attestation verification. Kept as a focused invariant helper for tests;
160	/// production execution requires `VerifiedArtifactManifest` above.
161	fn require_artifact_manifest_matches_intent(
162	    intent: &ReleaseIntentV1,
163	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
164	) -> Result<(), GraphError> {
165	    match (intent.artifact_slots.is_empty(), artifacts) {
166	        (true, None) => Ok(()),
167	        (true, Some(manifest)) | (false, Some(manifest)) => manifest
168	            .validate_for_intent(intent)
169	            .map_err(|source| GraphError::ArtifactManifest { source }),
170	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
171	            requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
172	        }),
173	    }
174	}
175	
176	/// The intent's operations as a DAG, built once per run. A constructed intent is already a proven DAG, so a failure
177	/// here means the intent was altered after validation.
178	pub(crate) fn operation_dag(intent: &ReleaseIntentV1) -> Result<Dag<ReleaseOperationId>, GraphError> {
179	    Dag::from_nodes(
180	        intent
181	            .operations
182	            .iter()
183	            .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec())),
184	        Order::Key,
185	    )
186	    .map_err(|violations| GraphError::ReleaseInvariant {
187	        detail: format!("the release operations do not form a valid DAG: {violations}"),
188	    })
189	}
190	
191	/// The wait for issued publishes to show. It opens when the first of them is issued and stays open until none is
192	/// outstanding, so a publish confirmed along the way does not start the window again, and it runs on the clock, so the
193	/// time spent looking counts. The looks keep their schedule from one settle to the next.
194	struct ConfirmationWave {
195	    opened: std::time::Instant,
196	    looks: u32,
197	}
198	
199	impl ConfirmationWave {
200	    fn open(now: std::time::Instant) -> Self {
201	        ConfirmationWave { opened: now, looks: 0 }
202	    }
203	}
204	
205	/// Looks at every issued operation until one is shown, so the run goes on with whatever that unlocks, or gives up
206	/// once the registries have had their whole window.
207	///
208	/// Each look is one observation per issued operation, and the issued operations are looked at together: the wait is
209	/// the slowest registry's, not the sum of them.
210	fn settle_issued<P: ReleaseProviderSet + ?Sized>(
211	    capability: &P,
212	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
213	    state: &mut ReleaseExecutionStateV1,
214	    issued: &mut BTreeSet<ReleaseOperationId>,
215	    wave: &mut ConfirmationWave,
216	) -> Result<(), GraphError> {
217	    let window = issued
218	        .iter()
219	        .map(|id| capability.confirmation_window(id))
220	        .max()
221	        .unwrap_or_default();
222	    loop {
223	        let mut progressed = false;
224	        for id in issued.clone() {
225	            // A look waits no longer than the window has left, so a registry that asks for long waits cannot hold it
226	            // past, and the looks of one pass share what is left.
227	            let patience = (wave.opened + window).saturating_duration_since(capability.now());
228	            if let Some(evidence) = capability.settle(&id, artifacts, patience)? {
229	                apply(state, &id, &OperationEvent::Confirmed { evidence })?;
230	                issued.remove(&id);
231	                progressed = true;
232	            }
233	        }
234	        if issued.is_empty() || progressed {
235	            return Ok(());
236	        }
237	        let remaining = (wave.opened + window).saturating_duration_since(capability.now());
238	        if remaining.is_zero() {
239	            let mut unconfirmed = issued.iter();
240	            let Some(first) = unconfirmed.next() else {
241	                return Ok(());
242	            };
243	            for other in unconfirmed {
244	                eprintln!("warning: {other} is also still not shown by its registry");
245	            }
246	            return Err(GraphError::RegistryPublishUnconfirmed {
247	                package: first.package.name().to_owned(),
248	                version: first.version.clone(),
249	                waited: window,
250	            });
251	        }
252	        let wait = crate::commands::release::provider::policy::visibility_backoff(wave.looks).min(remaining);
253	        capability.pause(wait);
254	        wave.looks = wave.looks.saturating_add(1);
255	    }
256	}
257	
258	/// A registry publish, which is issued now and shown later.
259	fn is_registry_effect(id: &ReleaseOperationId) -> bool {
260	    matches!(
261	        id.role,
262	        ReleaseOperationRole::RegistryPublish { .. } | ReleaseOperationRole::PlatformPublish { .. }
263	    )
264	}
265	
266	/// The pending operations that may start, in the intent's canonical order.
267	///
268	/// An operation may start when every one of its transitive prerequisites is `Published` or `AlreadySatisfied`. A
269	/// registry publish may also follow a registry publish that is only `issued`: npm takes a package whose dependency is
270	/// not visible yet, and everything announced (tag, release, uploads, publication) still waits for the version to be
271	/// shown. `ready` checks direct prerequisites; the ancestor check keeps a defective executor that recorded a later
272	/// operation's success before its prerequisite from making anything behind it eligible.
273	pub(crate) fn eligible_in(
274	    dag: &Dag<ReleaseOperationId>,
275	    state: &ReleaseExecutionStateV1,
276	    issued: &BTreeSet<ReleaseOperationId>,
277	) -> Vec<ReleaseOperationId> {
278	    let succeeded = |id: &ReleaseOperationId| state.operation_state(id).is_some_and(OperationState::is_success);
279	    dag.ready(
280	        |id| succeeded(id) || issued.contains(id),
281	        |id| state.operation_state(id) == Some(OperationState::Pending),
282	    )
283	    .filter_map(|ix| dag.key(ix).map(|id| (ix, id)))
284	    .filter(|(ix, id)| {
285	        dag.ancestors(&[*ix]).into_iter().all(|ancestor| {
286	            dag.key(ancestor).is_some_and(|prerequisite| {
287	                succeeded(prerequisite)
288	                    || (issued.contains(prerequisite) && is_registry_effect(id) && is_registry_effect(prerequisite))
289	            })
290	        })
291	    })
292	    .map(|(_, id)| id.clone())
293	    .collect()
294	}
