297	#[cfg(test)]
298	pub(crate) fn eligible_operations(
299	    intent: &ReleaseIntentV1,
300	    state: &ReleaseExecutionStateV1,
301	) -> Vec<ReleaseOperationId> {
302	    let dag = operation_dag(intent).expect("a test intent is a valid DAG");
303	    eligible_in(&dag, state, &BTreeSet::new())
304	}
